{"file_path":"src/render.js","content":"function cmp(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}

const sortedKeys = (map) => [...map.keys()].sort(cmp)

function scalarJson(n) {
  switch (n.t) {
    case 'string': return JSON.stringify(n.v)
    case 'integer': return n.v
    case 'float': return JSON.stringify(n.v)
    default: return String(n.v)
  }
}

function json(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n.t === 'table') {
    if (n.map.size === 0) return '{}'
    const parts = sortedKeys(n.map).map((k) => `${pad}${JSON.stringify(k)}: ${json(n.map.get(k), ind + 1)}`)
    return `{\n${parts.join(',\n')}\n${end}}`
  }
  if (n.t === 'array') {
    if (n.items.length === 0) return '[]'
    const parts = n.items.map((c) => pad + json(c, ind + 1))
    return `[\n${parts.join(',\n')}\n${end}]`
  }
  return scalarJson(n)
}

export function renderJson(root) {
  return json(root, 0) + '\n'
}

export function renderKeys(root) {
  const lines = []
  const walk = (n, path) => {
    if (n.t === 'table') {
      for (const k of sortedKeys(n.map)) {
        const p = path === null ? k : `${path}.${k}`
        lines.push(`${p} ${n.map.get(k).t}`)
        walk(n.map.get(k), p)
      }
    } else if (n.t === 'array') {
      n.items.forEach((c, i) => {
        const p = `${path}[${i}]`
        lines.push(`${p} ${c.t}`)
        walk(c, p)
      })
    }
  }
  walk(root, null)
  return lines.map((l) => l + '\n').join('')
}
"}

